from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        self.option_symbol = self.add_option("SPY", Resolution.MINUTE).symbol
        self.option_symbol.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-100, 100)
            .expiration(0, 1000)
        )

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_bar_end = None

        self.contract_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.expiration_liquidation_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.data_consolidated += self.on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

        self.schedule.on(
            self.date_rules.every_day(self.spy),
            self.time_rules.at(15, 45),
            self.expiration_eve_exit
        )

    def on_five_minute_bar(self, sender, bar):
        self.closes.add(float(bar.close))

        if not self.closes.is_ready:
            return

        closes = [self.closes[i] for i in range(20)]
        fast = sum(closes[:5]) / 5.0
        slow = sum(closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = bar.end_time
        if bullish_cross and (
            (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45))
            and (bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30))
        ):
            self.pending_entry_bar_end = bar_end

    def on_data(self, data):
        self.handle_unexpected_spy_position()
        self.handle_expiration_safety_exit()
        self.evaluate_profit_target(data)
        self.evaluate_pending_entry(data)

    def evaluate_pending_entry(self, data):
        if self.pending_entry_bar_end is None:
            return

        self.pending_entry_bar_end = None

        if self.has_option_position() or self.entry_order_is_open():
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Skipped entry: no SPY option chain in Slice.")
            return

        current_date = self.time.date()
        eligible_expirations = sorted({
            contract.expiry.date()
            for contract in chain
            if (contract.expiry.date() - current_date).days >= 7
        })

        if not eligible_expirations:
            self.debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expirations[0]
        calls = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() == selected_expiry
        ]

        if not calls:
            self.debug("Skipped entry: no calls at selected expiration.")
            return

        underlying_price = self.securities[self.spy].price
        contract = min(
            calls,
            key=lambda item: (abs(float(item.strike) - underlying_price), float(item.strike))
        )

        self.contract_symbol = contract.symbol
        self.entry_price = None
        self.exit_ticket = None
        self.entry_ticket = self.market_order(self.contract_symbol, 1)

        self.debug(
            f"Entry submitted: {self.contract_symbol} "
            f"expiry {selected_expiry}, one call contract."
        )

    def evaluate_profit_target(self, data):
        if not self.has_option_position() or self.entry_price is None:
            return

        if self.exit_order_is_open():
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.symbol == self.contract_symbol),
            None
        )
        if contract is None:
            return

        bid = float(contract.bid_price)
        ask = float(contract.ask_price)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.submit_exit("Profit target reached")

    def expiration_eve_exit(self):
        if not self.has_option_position() or self.contract_symbol is None:
            return

        expiry = self.contract_symbol.id.date.date()
        prior_trading_day = expiry - timedelta(days=1)
        exchange_hours = self.securities[self.spy].exchange.hours

        while not exchange_hours.is_date_open(prior_trading_day, False):
            prior_trading_day -= timedelta(days=1)

        if self.time.date() == prior_trading_day:
            self.submit_exit("Expiration-eve time stop")

    def handle_expiration_safety_exit(self):
        if not self.has_option_position() or self.contract_symbol is None:
            return

        expiry_date = self.contract_symbol.id.date.date()
        if self.time.date() >= expiry_date:
            if self.expiration_liquidation_date != self.time.date():
                self.expiration_liquidation_date = self.time.date()
                self.submit_exit("Expiration safety exit")

    def handle_unexpected_spy_position(self):
        quantity = self.portfolio[self.spy].quantity
        if quantity != 0:
            self.debug(
                f"Unexpected SPY exercise/assignment position ({quantity}); liquidating."
            )
            self.market_order(self.spy, -quantity)

    def submit_exit(self, reason):
        if not self.has_option_position() or self.contract_symbol is None:
            return

        if self.exit_order_is_open():
            return

        for order in self.transactions.get_open_orders(self.contract_symbol):
            self.transactions.cancel_order(order.id)

        quantity = self.portfolio[self.contract_symbol].quantity
        if quantity != 0:
            self.exit_ticket = self.market_order(self.contract_symbol, -quantity)
            self.debug(f"Exit submitted: {reason} for {self.contract_symbol}.")

    def on_order_event(self, order_event):
        if self.contract_symbol is None or order_event.symbol != self.contract_symbol:
            return

        if (
            self.entry_ticket is not None
            and order_event.order_id == self.entry_ticket.order_id
        ):
            if (
                order_event.status == OrderStatus.FILLED
                and order_event.fill_quantity > 0
                and self.entry_price is None
            ):
                self.entry_price = float(order_event.fill_price)
                self.debug(
                    f"Entry filled: {self.contract_symbol} at {self.entry_price:.2f}."
                )

            if order_event.status in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.order_id == self.exit_ticket.order_id
            and order_event.status in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            )
        ):
            if order_event.status == OrderStatus.FILLED:
                self.debug(f"Exit filled: {self.contract_symbol}.")
                self.contract_symbol = None
                self.entry_price = None
            self.exit_ticket = None

    def has_option_position(self):
        return (
            self.contract_symbol is not None
            and self.portfolio[self.contract_symbol].quantity != 0
        )

    def entry_order_is_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.status not in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            )
        )

    def exit_order_is_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.status not in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            )
        )

