from AlgorithmImports import *
from datetime import datetime, timedelta, time


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute, Market.USA, False)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute, Market.USA, False)
        option.SetFilter(lambda u: u.Strikes(-100, 100).Expiration(timedelta(0), timedelta(days=365)))
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.pending_entry_signal = False
        self.pending_signal_time = None
        self.held_option = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value
        averages_were_ready = self.fast.IsReady and self.slow.IsReady

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not averages_were_ready:
            return

        if previous_fast <= previous_slow and self.fast.Current.Value > self.slow.Current.Value:
            bar_time = bar.EndTime.time()
            if time(9, 45) <= bar_time <= time(14, 30):
                self.pending_entry_signal = True
                self.pending_signal_time = bar.EndTime

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()

        if self.held_option is not None:
            self.ManageOpenOption(slice)

        if self.pending_entry_signal:
            self.pending_entry_signal = False

            if self.pending_signal_time != self.Time:
                return

            if self.no_entry_date == self.Time.date():
                return

            if self.held_option is not None or self.HasOpenEntryOrder():
                return

            self.TryEnter(slice)

    def TryEnter(self, slice):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: entry skipped; no SPY option chain")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug(f"{self.Time}: entry skipped; no qualifying call expiration")
            return

        selected_expiry = expiries[0]
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() == selected_expiry
        ]

        if not calls:
            self.Debug(f"{self.Time}: entry skipped; no qualifying calls at selected expiration")
            return

        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0:
            self.Debug(f"{self.Time}: entry skipped; invalid SPY price")
            return

        contract = min(
            calls,
            key=lambda c: (abs(float(c.Strike) - underlying_price), float(c.Strike))
        )

        ticket = self.MarketOrder(contract.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: submitted entry for {contract.Symbol}")

    def ManageOpenOption(self, slice):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            self.SubmitExit("expiration processing")
            return

        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            datetime.combine(expiry_date, time.min)
        ).date()

        if self.Time.date() == previous_trading_day and self.Time.time() == time(15, 45):
            self.SubmitExit("pre-expiration time stop")
            return

        if self.entry_price is None or self.HasOpenExitOrder():
            return

        quote = slice.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_option is None or self.HasOpenExitOrder():
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id, "Replacing with market exit")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            ticket = self.MarketOrder(self.held_option, -quantity)
            self.exit_order_id = ticket.OrderId
            self.Debug(f"{self.Time}: submitted exit for {self.held_option}; {reason}")

    def HandleUnexpectedSpyPosition(self):
        if not self.Portfolio[self.spy].Invested:
            return

        spy_open_orders = self.Transactions.GetOpenOrders(self.spy)
        if not spy_open_orders:
            self.Debug(f"{self.Time}: unexpected SPY exercise/assignment position; liquidating")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

    def HasOpenEntryOrder(self):
        return self.IsOrderOpen(self.entry_order_id)

    def HasOpenExitOrder(self):
        return self.IsOrderOpen(self.exit_order_id)

    def IsOrderOpen(self, order_id):
        if order_id is None:
            return False

        order = self.Transactions.GetOrderById(order_id)
        return order is not None and order.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        if order_event.OrderId == self.entry_order_id and order_event.FillQuantity > 0:
            self.held_option = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.entry_order_id = None
            self.Debug(f"{self.Time}: entered {self.held_option} at {self.entry_price}")

        if order_event.OrderId == self.exit_order_id and order_event.FillQuantity < 0:
            if not self.Portfolio[order_event.Symbol].Invested:
                self.Debug(f"{self.Time}: exited {order_event.Symbol} at {order_event.FillPrice}")
                self.held_option = None
                self.entry_price = None
                self.exit_order_id = None

