        self.option_symbol.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(timedelta(0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.pending_entry_time = None
        self.held_option = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.spy_cleanup_order_id = None
        self.blocked_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if previous_fast is None or previous_slow is None or not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = previous_fast <= previous_slow and self.fast.Current.Value > self.slow.Current.Value
        end_time = bar.EndTime

        if bullish_cross and (
            (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
            and (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        ):
            self.pending_entry_time = end_time

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()

        if self.held_option is not None and self.held_expiry is not None:
            if self.Time.date() >= self.held_expiry.date():
                self.blocked_entry_date = self.Time.date()
                self.SubmitExit("expiration processing")
            else:
                self.CheckTimeExit()
                self.CheckProfitTarget(slice)

        if self.pending_entry_time is not None:
            if self.pending_entry_time == self.Time:
                self.TryEnter(slice)
            self.pending_entry_time = None

    def TryEnter(self, slice):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_option is not None or self.IsOpen(self.entry_order_id) or self.IsOpen(self.exit_order_id):
            return

        if self.option_symbol not in slice.OptionChains:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - self.Time.date()).days >= 7
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() == selected_expiry
        ]

        if not calls:
            self.Debug(f"{self.Time}: Entry skipped: no calls at selected expiration.")
            return

        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped: invalid SPY price.")
            return

        contract = min(calls, key=lambda item: (abs(item.Strike - underlying_price), item.Strike))
        ticket = self.MarketOrder(contract.Symbol, 1, False, "Bullish 5-minute MA crossover")
        self.entry_order_id = ticket.OrderId
        self.held_option = contract.Symbol
        self.held_expiry = contract.Expiry
        self.entry_price = None

        self.Debug(
            f"{self.Time}: Entry submitted: {contract.Symbol.Value}, expiry {contract.Expiry.date()}, "
            f"strike {contract.Strike}."
        )

    def CheckProfitTarget(self, slice):
        if self.entry_price is None or self.entry_price <= 0 or self.IsOpen(self.exit_order_id):
            return

        if self.option_symbol not in slice.OptionChains:
            return

        contract = next(
            (item for item in slice.OptionChains[self.option_symbol] if item.Symbol == self.held_option),
            None
        )

        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("50% profit target")

    def CheckTimeExit(self):
        if self.Time.hour != 15 or self.Time.minute != 45:
            return

        if self.NextTradingDate(self.Time.date()) == self.held_expiry.date():
            self.SubmitExit("day-before-expiration time stop")

    def NextTradingDate(self, date):
        candidate = date + timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate, False):
            candidate += timedelta(days=1)

        return candidate

    def SubmitExit(self, reason):
        if self.held_option is None or self.IsOpen(self.exit_order_id):
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id, "Cancelling other exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_option, -quantity, False, reason)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Exit submitted for {self.held_option.Value}: {reason}.")

    def HandleUnexpectedSpyPosition(self):
        if self.Portfolio[self.spy].Quantity == 0 or self.IsOpen(self.spy_cleanup_order_id):
            return

        quantity = self.Portfolio[self.spy].Quantity
        ticket = self.MarketOrder(self.spy, -quantity, False, "Unexpected option exercise or assignment cleanup")
        self.spy_cleanup_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Unexpected SPY exercise/assignment position; liquidation submitted.")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entry filled: {self.held_option.Value} at {self.entry_price:.2f}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"{self.Time}: Entry order did not fill: {order_event.Status}.")
                self.entry_order_id = None
                self.held_option = None
                self.held_expiry = None
                self.entry_price = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled: {order_event.Symbol.Value} at {order_event.FillPrice:.2f}.")
                self.held_option = None
                self.held_expiry = None
                self.entry_price = None
                self.entry_order_id = None
                self.exit_order_id = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

        if order_event.OrderId == self.spy_cleanup_order_id and order_event.Status in (
            OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
        ):
            self.spy_cleanup_order_id = None

    def IsOpen(self, order_id):
        if order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(order_id)
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        )

