from AlgorithmImports import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Consolidators import TradeBarConsolidator
from datetime import timedelta, time as clock_time


class FiveMinuteSpyCallCrossover(QCAlgorithm):

    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity("SPY", Resolution.MINUTE).symbol
        self.securities[self.spy].set_data_normalization_mode(DataNormalizationMode.RAW)

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-100, 100)
            .expiration(0, 365)
        )
        self.option_symbol = option.symbol

        self.closes = []
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_bar_end = None

        self.contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_price = None
        self.expiration_blocked_dates = set()

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.data_consolidated += self.on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

    def on_five_minute_bar(self, sender, bar):
        self.closes.append(bar.close)
        if len(self.closes) > 20:
            self.closes.pop(0)

        if len(self.closes) < 20:
            return

        fast = sum(self.closes[-5:]) / 5.0
        slow = sum(self.closes) / 20.0

        crossed_up = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end_time = bar.end_time.time()
        eligible_time = (
            clock_time(9, 45) <= bar_end_time <= clock_time(14, 30)
        )

        if (
            crossed_up
            and eligible_time
            and not self.has_option_position()
            and not self.entry_order_open()
            and self.time.date() not in self.expiration_blocked_dates
        ):
            self.pending_entry_bar_end = bar.end_time

    def on_data(self, slice):
        self.handle_unexpected_spy_position()
        self.handle_expiration_processing()
        self.handle_option_exits(slice)

        if self.pending_entry_bar_end is not None:
            pending_time = self.pending_entry_bar_end
            self.pending_entry_bar_end = None

            if (
                self.time == pending_time
                and not self.has_option_position()
                and not self.entry_order_open()
                and self.time.date() not in self.expiration_blocked_dates
            ):
                self.try_enter(slice)

    def try_enter(self, slice):
        chains = list(slice.option_chains.values())
        if not chains:
            self.debug(f"{self.time}: Entry skipped: no option chain in Slice.")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)
        contracts = []

        for chain in chains:
            contracts.extend(list(chain))

        valid_expiries = sorted(
            {
                contract.symbol.id.date.date()
                for contract in contracts
                if contract.symbol.id.option_right == OptionRight.CALL
                and contract.symbol.id.date.date() >= minimum_expiry
            }
        )

        if not valid_expiries:
            self.debug(f"{self.time}: Entry skipped: no call expiry at least 7 calendar days away.")
            return

        selected_expiry = valid_expiries[0]
        calls = [
            contract
            for contract in contracts
            if contract.symbol.id.option_right == OptionRight.CALL
            and contract.symbol.id.date.date() == selected_expiry
        ]

