    def _try_enter(self, data):
        if self._no_entry_date == self.Time.date():
            self.Debug(f"{self.Time}: Entry skipped: expiration-processing day.")
            return

        if self._held_option is not None or self._entry_order_is_open():
            self.Debug(f"{self.Time}: Entry skipped: option position or entry order already exists.")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain in Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call and contract.Expiry.date() >= minimum_expiry
        })

        if not valid_expiries:
            self.Debug(f"{self.Time}: Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = valid_expiries[0]
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
        ]

        if not calls:
            self.Debug(f"{self.Time}: Entry skipped: no eligible calls at selected expiration.")
            return

        underlying_price = self.Securities[self.spy].Price
        contract = min(
            calls,
            key=lambda c: (abs(c.Strike - underlying_price), c.Strike)
        )

        self._entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self._entry_order_id = self._entry_ticket.OrderId
        self.Debug(
