        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50% profit target")

    def _handle_expiration_processing(self):
        if self._held_option is None or self._held_expiry is None:
            return

        if self.Time.date() >= self._held_expiry:
            self._no_entry_date = self.Time.date()
            if self.Portfolio[self._held_option].Invested:
                self._submit_exit("expiration processing")

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy].Invested:
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position from exercise/assignment; liquidating."
            )
            self.Liquidate(self.spy)

    def _submit_exit(self, reason):
        if self._held_option is None or not self.Portfolio[self._held_option].Invested:
            return

        for ticket in self.Transactions.GetOpenOrderTickets():
            order = self.Transactions.GetOrderById(ticket.OrderId)
            if order is not None and order.Symbol == self._held_option and order.Quantity < 0:
                ticket.Cancel("Replacing open exit order.")

        if self._exit_order_is_open():
            return

        quantity = -self.Portfolio[self._held_option].Quantity
        self._exit_ticket = self.MarketOrder(self._held_option, quantity)
        self._exit_order_id = self._exit_ticket.OrderId
        self.Debug(f"{self.Time}: Exit submitted for {self._held_option.Value}: {reason}.")

    def _previous_trading_day(self, expiry_date):
        expiry = datetime(expiry_date.year, expiry_date.month, expiry_date.day)
        return self.Securities[self.spy].Exchange.Hours.GetPreviousMarketOpen(
            expiry, False
        ).date()

    def _entry_order_is_open(self):
        if self._entry_ticket is None:
            return False

        return self._entry_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def _exit_order_is_open(self):
        if self._exit_ticket is None:
            return False

        return self._exit_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def OnOrderEvent(self, orderEvent):
        if orderEvent.OrderId == self._entry_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self._held_option = orderEvent.Symbol
                self._entry_price = orderEvent.FillPrice
                self._held_expiry = orderEvent.Symbol.ID.Date.date()
                self._entry_ticket = None
                self._entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled: {self._held_option.Value} "
                    f"at {self._entry_price}."
                )
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: Entry order canceled or invalid.")
                self._entry_ticket = None
                self._entry_order_id = None

        if orderEvent.OrderId == self._exit_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled: {orderEvent.Symbol.Value}.")
                self._exit_ticket = None
                self._exit_order_id = None
                self._held_option = None
                self._held_expiry = None
                self._entry_price = None
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self._exit_ticket = None
                self._exit_order_id = None

