from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption(self.spy, Resolution.Minute)
        self.option_canonical = option.Symbol
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False

        self.held_option = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_cleanup_order_id = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.closes.append(bar.Close)

        if len(self.closes) < 20:
            return

        values = list(self.closes)
        fast = sum(values[-5:]) / 5.0
        slow = sum(values) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = bar.EndTime
        if bullish_cross and (
            (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
            and (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        ):
            self.pending_entry_signal = True

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()

        if self.held_option is not None:
            self.HandleExpirationAndTimeStop()
            self.HandleProfitTarget(data)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Quantity != 0:
            return

        if self.IsOrderOpen(self.entry_order_id):
            return

        chain = data.OptionChains.get(self.option_canonical)
        if chain is None:
            self.Debug("Entry skipped: no option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_expiries = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Right == OptionRight.Call
                and contract.Expiry.date() >= minimum_expiry
            }
        )

        if not eligible_expiries:
            self.Debug("Entry skipped: no call expiry at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        spot = self.Securities[self.spy].Price
        candidates = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
        ]

        if not candidates:
            self.Debug("Entry skipped: no eligible call contract.")
            return

        contract = min(candidates, key=lambda c: (abs(c.Strike - spot), c.Strike))
        ticket = self.MarketOrder(contract.Symbol, 1, tag="Bullish 5-minute MA crossover")
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {contract.Symbol} expiry {selected_expiry} strike {contract.Strike}."
        )

    def HandleProfitTarget(self, data):
        if self.entry_price is None or self.Portfolio[self.held_option].Quantity <= 0:
            return

        contract = self.FindHeldContract(data)
        if contract is None:
            return

        if contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("50% profit target", replace_existing=True)

    def HandleExpirationAndTimeStop(self):
        if self.Portfolio[self.held_option].Quantity <= 0:
            return

        expiry = self.held_option.ID.Date.date()

        if self.Time.date() >= expiry:
            self.no_entry_date = self.Time.date()
            self.SubmitExit("expiration-day protection")
            return

        previous_trading_day = expiry - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        while not exchange_hours.IsDateOpen(previous_trading_day):
            previous_trading_day -= timedelta(days=1)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self.SubmitExit("pre-expiration time stop")

    def SubmitExit(self, reason, replace_existing=False):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.IsOrderOpen(self.exit_order_id):
            if not replace_existing:
                return

            old_ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
            if old_ticket is not None:
                old_ticket.Cancel("Replacing exit order")

        ticket = self.MarketOrder(self.held_option, -quantity, tag=reason)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {reason}.")

    def FindHeldContract(self, data):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_option:
                    return contract
        return None

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.IsOrderOpen(self.equity_cleanup_order_id):
            return

        ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise/assignment equity cleanup"
        )
        self.equity_cleanup_order_id = ticket.OrderId
        self.Debug("Unexpected SPY exercise/assignment position detected; liquidation submitted.")

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug("Entry order did not fill.")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}."
                )
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_option = None
                    self.entry_price = None
                    self.exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if order_event.OrderId == self.equity_cleanup_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.equity_cleanup_order_id = None

    def IsOrderOpen(self, order_id):
