        self.HandleExpirationProtection()

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnterCall(data)

        self.TryExitForProfit(data)
        self.TryExitBeforeExpiration()

    def TryEnterCall(self, data):
        if self.expiration_blocked_date == self.Time.date():
