        if self.held_option is None or self.entry_fill_price is None:
            return

        if not self.Securities[self.held_option].Invested:
            return

        if self.exit_order_id is not None:
            return

        contract = self.GetContractFromSlice(data, self.held_option)
        if contract is None:
            return

        if contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
