        if self.held_option is None or self.held_expiry is None:
            return

        if not self.Securities[self.held_option].Invested:
            return

        if self.exit_order_id is not None:
            return

        previous_trading_day = self.GetPreviousTradingDay(self.held_expiry)
        if (
            self.Time.date() == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self.CancelOpenExitOrder()
            ticket = self.MarketOrder(
                self.held_option,
                -self.Securities[self.held_option].Holdings.Quantity
            )
            self.exit_order_id = ticket.OrderId
            self.Debug(f"{self.Time}: Pre-expiration exit submitted for {self.held_option}.")

    def HandleExpirationProtection(self):
        if self.held_option is None or self.held_expiry is None:
            return

        if self.Time.date() < self.held_expiry:
            return

        self.expiration_blocked_date = self.Time.date()

        if self.Securities[self.held_option].Invested and self.exit_order_id is None:
            self.CancelOpenExitOrder()
            ticket = self.MarketOrder(
                self.held_option,
                -self.Securities[self.held_option].Holdings.Quantity
            )
            self.exit_order_id = ticket.OrderId
            self.Debug(f"{self.Time}: Expiration protection liquidation submitted for {self.held_option}.")

    def HandleUnexpectedSpyPosition(self):
        if not self.Securities[self.spy].Invested:
            self.spy_liquidation_submitted = False
            return

        if not self.spy_liquidation_submitted:
            quantity = self.Securities[self.spy].Holdings.Quantity
            self.MarketOrder(self.spy, -quantity)
            self.spy_liquidation_submitted = True
            self.Debug(
                f"{self.Time}: Unexpected SPY exercise/assignment position detected; "
                f"liquidation submitted for {quantity} shares."
            )

    def GetContractFromSlice(self, data, symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def GetPreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def CancelOpenExitOrder(self):
        if self.exit_order_id is None:
            return

        ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
        if ticket is not None:
            ticket.Cancel()

        self.exit_order_id = None

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled for {self.held_option} "
                    f"at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: Entry order canceled or invalid.")
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled for {order_event.Symbol}.")
                self.exit_order_id = None
                self.held_option = None
                self.held_expiry = None
                self.entry_fill_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

