from AlgorithmImports import *
from datetime import datetime, timedelta, time


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(lambda u: u.IncludeWeeklys().Strikes(-100, 100).Expiration(0, 365))
        self.option_symbol = option.Symbol

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.minute_closes = {}

        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_exit_order_id = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_spy_minute_bar(spy_bar, slice)

        self._evaluate_option_exits(slice)

    def _process_spy_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        session_open = datetime.combine(end_time.date(), time(9, 30))

        if end_time < session_open + timedelta(minutes=1) or end_time.time() > time(16, 0):
            return

        elapsed_minutes = int((end_time - session_open).total_seconds() // 60)
        bucket_minutes = ((elapsed_minutes + 4) // 5) * 5
        bucket_end = session_open + timedelta(minutes=bucket_minutes)

        self.minute_closes[end_time] = bar.Close

        if end_time != bucket_end:
            return

        required_times = [bucket_end - timedelta(minutes=i) for i in range(4, -1, -1)]
        complete = all(t in self.minute_closes for t in required_times)

        if complete:
            self._process_completed_five_minute_bar(
                bucket_end,
                self.minute_closes[bucket_end],
                slice
            )

        for timestamp in required_times:
            self.minute_closes.pop(timestamp, None)

    def _process_completed_five_minute_bar(self, bar_end: datetime, close: float, slice: Slice):
        self.closes.Add(close)

        if not self.closes.IsReady:
            return

        fast = sum(self.closes[i] for i in range(5)) / 5.0
        slow = sum(self.closes[i] for i in range(20)) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain in Slice.")
            return

        eligible = [
            contract for contract in chain
            if (contract.Expiry.date() - self.Time.date()).days >= 7
        ]

        if not eligible:
            self.Debug(f"{self.Time}: Entry skipped: no expiration at least 7 calendar days away.")
            return

        expiration = min(contract.Expiry.date() for contract in eligible)
        calls = [
            contract for contract in eligible
            if contract.Expiry.date() == expiration and contract.Right == OptionRight.Call
        ]

        if not calls:
            self.Debug(f"{self.Time}: Entry skipped: selected expiration has no calls.")
            return

        underlying_price = self.Securities[self.spy].Price
        selected = min(
            calls,
            key=lambda contract: (abs(contract.Strike - underlying_price), contract.Strike)
        )

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_contract = selected.Symbol
        self.entry_price = None

        self.Debug(
            f"{self.Time}: Entry submitted for 1 {selected.Symbol}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}."
        )

    def _evaluate_option_exits(self, slice: Slice):
        if self.held_contract is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0 or self.exit_order_id is not None:
            return

        if self._is_pre_expiration_time_stop():
            self._submit_exit("pre-expiration time stop")
            return

        contract = self._find_contract_in_slice(slice, self.held_contract)
        if contract is None:
            return

        if contract.BidPrice > 0 and contract.AskPrice > 0:
            midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
            if midpoint >= 1.50 * self.entry_price:
                self._submit_exit("50% profit target")

    def _find_contract_in_slice(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _is_pre_expiration_time_stop(self) -> bool:
        if self.Time.time() != time(15, 45):
            return False

        expiry_date = self.held_contract.ID.Date.date()
        next_open = self.Securities[self.spy].Exchange.Hours.GetNextMarketOpen(
            self.Time + timedelta(minutes=1),
            False
        )
        return next_open.date() == expiry_date

    def _handle_expiration(self, slice: Slice):
        if self.held_contract is None:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            if self.Portfolio[self.held_contract].Quantity != 0 and self.exit_order_id is None:
                self._submit_exit("expiration processing")

    def _submit_exit(self, reason: str):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id, "Replacing open exit order")

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Exit submitted for {self.held_contract}: {reason}.")

    def _handle_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity == 0 or self.equity_exit_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -spy_quantity)
        self.equity_exit_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: Unexpected SPY equity position from exercise/assignment; "
            f"submitted liquidation."
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"{self.Time}: Entry filled for {order_event.Symbol} "
                    f"at {self.entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: Entry order {order_event.OrderId} was not filled.")
                self.entry_order_id = None
                self.held_contract = None
                self.entry_price = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled for {order_event.Symbol} "
                    f"at {order_event.FillPrice:.2f}."
                )
                self.exit_order_id = None
                self.held_contract = None
                self.entry_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

        if order_event.OrderId == self.equity_exit_order_id:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
                self.equity_exit_order_id = None

