                timedelta(days=0), timedelta(days=365)
            )
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.held_contract = None
        self.held_expiry = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_ticket = None
        self.expiration_exit_date = None
        self.equity_liquidation_pending = False

    def OnFiveMinuteBar(self, sender, bar):
        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if prior_fast is None or prior_slow is None:
            return

        end_time = bar.EndTime
        eligible_time = (
            (end_time.hour == 9 and end_time.minute >= 45) or
            (end_time.hour >= 10 and end_time.hour < 14) or
            (end_time.hour == 14 and end_time.minute <= 30)
        )

        if (
            eligible_time
            and prior_fast <= prior_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            self.pending_entry_signal = True

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()

        if self.held_contract is not None:
            self.HandleExpirationProtection()
            self.HandleTimeStop()
            self.HandleProfitTarget(slice)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.Time.date() == self.expiration_exit_date:
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0:
            return

        if self.entry_order_id is not None:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expirations[0]
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
        ]

        if not calls:
            self.Debug("Entry skipped: selected expiration has no eligible calls.")
            return

        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0:
            self.Debug("Entry skipped: SPY price unavailable for strike selection.")
            return

        selected = min(
            calls,
            key=lambda contract: (abs(contract.Strike - underlying_price), contract.Strike)
        )

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_contract = selected.Symbol
        self.held_expiry = selected.Expiry.date()
        self.entry_price = None
        self.exit_ticket = None
        self.Debug(
            f"Entry submitted: bought 1 SPY call {selected.Symbol} expiring {selected.Expiry.date()}."
        )

    def HandleProfitTarget(self, slice):
        if self.entry_price is None or self.held_contract is None:
            return

        if self.ExitOrderIsOpen():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.Symbol == self.held_contract),
            None
        )
        if contract is None or contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("Profit target reached")

    def HandleTimeStop(self):
        if self.held_contract is None or self.held_expiry is None:
            return

        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            self.held_expiry
        )

        if (
            self.Time.date() == previous_trading_day.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
            and not self.ExitOrderIsOpen()
        ):
            self.SubmitExit("Pre-expiration 15:45 time stop")

    def HandleExpirationProtection(self):
        if self.held_contract is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry:
            self.expiration_exit_date = self.Time.date()
            if not self.ExitOrderIsOpen():
                self.SubmitExit("Expiration protection")
            self.Debug("Expiration processing: liquidation submitted; entries blocked today.")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self.ExitOrderIsOpen():
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"Exit submitted: {reason}.")

    def ExitOrderIsOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        ]

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            self.equity_liquidation_pending = False
            return

        if not self.equity_liquidation_pending:
            self.equity_liquidation_pending = True
            self.Debug(
                f"Unexpected SPY equity position ({quantity}) from exercise/assignment; liquidating."
            )
            self.MarketOrder(self.spy, -quantity)

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug("Entry order was not filled.")
                self.entry_order_id = None
                if (
                    self.held_contract is not None
                    and self.Portfolio[self.held_contract].Quantity == 0
                ):
                    self.held_contract = None
                    self.held_expiry = None
                    self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_contract} at {order_event.FillPrice:.2f}.")
                if (
                    self.held_contract is not None
                    and self.Portfolio[self.held_contract].Quantity == 0
                ):
                    self.held_contract = None
                    self.held_expiry = None
                    self.entry_price = None
                    self.exit_ticket = None

        self.HandleUnexpectedEquityPosition()

